grep -l -i 'music.youtube' ~/.local/share/applications/*.desktop /usr/share/applications/*.desktop 2>/dev/null | while read f; do echo "== $f"; grep -E '^(Name|Exec|StartupWMClass|Icon)=' "$f"; done; echo "--- open windows:"; hyprctl clients -j | jq -r '.[].class' | grep -i -E 'music|youtube' || echo "(none open)"; echo "--- existing:"; ~/.claude/skills/taskbar-icons/scripts/icon-set --list | tr '\n' ' '; echo; grep -o -E '"(youtube|play|music)": "[^"]*"' ~/.config/omarchy/bar/modules/taskbar-icons.js
